class Solution { fun createBinaryTree(descriptions:Array<IntArray>):TreeNode?{val nodes=HashMap<Int,TreeNode>();val children=HashSet<Int>();for(description in descriptions){val parent=nodes.getOrPut(description[0]){TreeNode(description[0])};val child=nodes.getOrPut(description[1]){TreeNode(description[1])};if(description[2]==1)parent.left=child else parent.right=child;children.add(description[1])};return nodes.entries.first{it.key !in children}.value} }
